// Reverse: walk forward rewiring each next pointer backwards.
static ListNode reverse(ListNode head) {
    ListNode prev = null;
    while (head != null) {
        ListNode next = head.next;   // save before clobbering
        head.next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

// Floyd: slow moves 1, fast moves 2. If they meet there is a cycle.
// Reset one to head and advance both by 1 to find the cycle entry.
static ListNode cycleStart(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next; fast = fast.next.next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) { slow = slow.next; fast = fast.next; }
            return slow;
        }
    }
    return null;
}

class ListNode:
    def __init__(self, val: int = 0, nxt: 'ListNode | None' = None):
        self.val, self.next = val, nxt

# Reverse: rewire each next pointer backwards as you walk forward.
def reverse(head: ListNode | None) -> ListNode | None:
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next   # save-rewire-advance
    return prev

# Floyd: slow moves 1, fast moves 2. Meeting means a cycle. Reset one pointer
# to head, advance both by 1, and they meet at the cycle entry.
def cycle_start(head: ListNode | None) -> ListNode | None:
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            slow = head
            while slow is not fast:
                slow, fast = slow.next, fast.next
            return slow
    return None

# Middle of the list — the same fast/slow idea.
def middle(head: ListNode | None) -> ListNode | None:
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    return slow

