typedef struct Node { int val; struct Node *next; } Node;

Node *node_new(int v) {
    Node *n = malloc(sizeof *n);
    if (!n) exit(1);
    n->val = v; n->next = NULL;
    return n;
}

/* Reverse: rewire each next backwards while walking forward. */
Node *reverse(Node *head) {
