    while (head) {
        Node *next = head->next;   /* save before clobbering */
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

/* Floyd: meeting means a cycle. Reset one pointer to head, step both by 1,
   and they meet at the cycle entry. */
Node *cycleStart(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next; fast = fast->next->next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) { slow = slow->next; fast = fast->next; }
            return slow;
        }
    }
    return NULL;
}

/* You own the memory. Save next BEFORE freeing — reading n->next after
   free(n) is undefined behaviour, and it often appears to work. */
void list_free(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

type ListNode struct {
	Val  int
	Next *ListNode
}

// Reverse: rewire each Next backwards while walking forward.
func reverse(head *ListNode) *ListNode {
	var prev *ListNode
	for head != nil {
		head.Next, prev, head = prev, head, head.Next
	}
	return prev
}

// Floyd: slow moves 1, fast moves 2. Meeting means a cycle; reset one to head
// and step both by 1 to land on the cycle entry.
func cycleStart(head *ListNode) *ListNode {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow, fast = slow.Next, fast.Next.Next
		if slow == fast {
			slow = head
			for slow != fast {
				slow, fast = slow.Next, fast.Next
			}
			return slow
		}
	}
	return nil
}

// A dummy head removes the "is this the first node?" special case from
// every insert and delete.
func removeVal(head *ListNode, v int) *ListNode {
	dummy := &ListNode{Next: head}
	for cur := dummy; cur.Next != nil; {
		if cur.Next.Val == v {
			cur.Next = cur.Next.Next
		} else {
			cur = cur.Next
		}
	}
	return dummy.Next
}
